41	                }
42	            });
43	        }
44	    } else {
45	        if constexpr (tile_shape::isRowMajor) {
46	            cpu::parallel_for_rows(validRow, validCol, [&](std::size_t r) {
47	                for (std::size_t c = 0; c < validCol; ++c) {
