34	template <
35	    typename TileDataDst, typename TileDataSrc0, typename TileDataSrc1, unsigned elementsPerRepeat,
36	    unsigned blockSizeElem, unsigned dstRowStride, unsigned src0RowStride = dstRowStride,
37	    unsigned src1RowStride = dstRowStride>
38	__tf__ PTO_INTERNAL void TAdd(
39	    typename TileDataDst::TileDType __out__ dst, typename TileDataSrc0::TileDType __in__ src0,
40	    typename TileDataSrc1::TileDType __in__ src1, unsigned validRows, unsigned validCols)
41	{
42	    using T = typename TileDataDst::DType;
43	    __ubuf__ T* dstPtr = (__ubuf__ T*)__cce_get_tile_ptr(dst);
44	    __ubuf__ T* src0Ptr = (__ubuf__ T*)__cce_get_tile_ptr(src0);
45	    __ubuf__ T* src1Ptr = (__ubuf__ T*)__cce_get_tile_ptr(src1);
46	    if constexpr (dstRowStride == src0RowStride && dstRowStride == src1RowStride) {
47	        BinaryInstr<AddOp<T>, T, TileDataDst, elementsPerRepeat, blockSizeElem, dstRowStride>(
48	            dstPtr, src0Ptr, src1Ptr, validRows, validCols);
49	    } else {
50	        BinaryInstr<AddOp<T>, T, elementsPerRepeat, blockSizeElem, dstRowStride, src0RowStride, src1RowStride>(
51	            dstPtr, src0Ptr, src1Ptr, validRows, validCols);
52	    }
53	    return;
54	}
