62	// Soft SYNCALL: GM shared-counter barrier. CoreType selects AIV-only / AIC-only / MIX.
63	// Hard Mode with a workspace argument is accepted but ignores gmWorkspace (same as SYNCALL()).
64	template <
65	    SyncAllMode Mode, SyncCoreType CoreType = SyncCoreType::AIVOnly, typename GlobalData,
66	    std::enable_if_t<is_global_data_v<GlobalData>, int> = 0>
67	PTO_INST void SYNCALL(GlobalData& gmWorkspace, int32_t usedCores = 0)
68	{
69	#if defined(PTO_NPU_ARCH_A2A3) || defined(PTO_NPU_ARCH_A5) || defined(__CPU_SIM)
70	    if constexpr (Mode == SyncAllMode::Hard) {
71	        (void)gmWorkspace;
72	        (void)usedCores;
73	        SYNCALL_IMPL<CoreType>();
74	    } else if constexpr (CoreType == SyncCoreType::AIVOnly) {
75	#ifndef __PTO_AUTO__
76	        SYNCALL_SOFT_IMPL<CoreType>(gmWorkspace.data(), usedCores);
77	#endif
78	    } else if constexpr (CoreType == SyncCoreType::AICOnly) {
79	#ifndef __PTO_AUTO__
80	        SYNCALL_SOFT_AIC_IMPL(gmWorkspace.data(), usedCores);
81	#endif
82	    } else {
83	#ifndef __PTO_AUTO__
84	        SYNCALL_SOFT_MIX_IMPL<CoreType>(gmWorkspace.data(), usedCores);
85	#endif
86	    }
87	#else
88	    PTO_STATIC_ASSERT(Mode != Mode, "SYNCALL is not supported on this backend.");
89	#endif
90	}
91	
92	template <typename... WaitEvents>
