19	void BinaryElementTileOp_Impl(TileDataDst& dstTile, TileDataSrc0& src0Tile, TileDataSrc1& src1Tile, size_t extra = 0)
20	{
21	    static_assert(
22	        std::is_same_v<typename TileDataDst::TileDType, typename TileDataSrc0::TileDType> &&
23	        std::is_same_v<typename TileDataDst::TileDType, typename TileDataSrc1::TileDType> &&
24	        "Underlying data types in tiles should be the same");
25	
26	    assert(
27	        dstTile.GetValidRow() == src0Tile.GetValidRow() && dstTile.GetValidCol() == src0Tile.GetValidCol() &&
28	        dstTile.GetValidRow() == src1Tile.GetValidRow() && dstTile.GetValidCol() == src1Tile.GetValidCol() &&
29	        "Valid shapes of all I/O tiles should be the same");
30	
31	    typename TileDataDst::TileDType dst = dstTile.data();
32	    typename TileDataSrc0::TileDType src0 = src0Tile.data();
33	    typename TileDataSrc1::TileDType src1 = src1Tile.data();
34	
35	    const unsigned int validRow = dstTile.GetValidRow();
36	    const unsigned int validCol = dstTile.GetValidCol();
37	
38	    using DType = typename TileDataDst::DType;
39	    if constexpr (TileDataDst::isRowMajor) {
40	        cpu::parallel_for_rows(validRow, validCol, [&](std::size_t r) {
41	            for (std::size_t c = 0; c < validCol; ++c) {
42	                const std::size_t idxDst = GetTileElementOffset<TileDataDst>(r, c);
43	                const std::size_t idxSrc0 = GetTileElementOffset<TileDataSrc0>(r, c);
44	                const std::size_t idxSrc1 = GetTileElementOffset<TileDataSrc1>(r, c);
45	                ElementOpCal<DType, op>::apply(dst[idxDst], src0[idxSrc0], src1[idxSrc1], extra);
46	            }
47	        });
48	    } else {
49	        cpu::parallel_for_rows(validCol, validRow, [&](std::size_t c) {
50	            for (std::size_t r = 0; r < validRow; ++r) {
51	                const std::size_t idxDst = GetTileElementOffset<TileDataDst>(r, c);
52	                const std::size_t idxSrc0 = GetTileElementOffset<TileDataSrc0>(r, c);
53	                const std::size_t idxSrc1 = GetTileElementOffset<TileDataSrc1>(r, c);
54	                ElementOpCal<DType, op>::apply(dst[idxDst], src0[idxSrc0], src1[idxSrc1], extra);
55	            }
56	        });
57	    }
